import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { UserService } from 'src/app/services/emis/user.service';
import { UserSessionService } from 'src/app/services/usersession.service';

@Component({
  selector: 'app-leave-history',
  templateUrl: './leave-history.page.html',
  styleUrls: ['./leave-history.page.scss'],
})
export class LeaveHistoryPage implements OnInit {
  history: any[];
  username: any;
  routeData: any;
  userid: any;
  phone: any;
  distric: any;
  name: any;

  constructor(private userService: UserService,private usersessionService: UserSessionService,
    private router: Router,private route: ActivatedRoute,) { }

  ngOnInit() {
  }

  ionViewDidEnter() {
    this.username = this.usersessionService.emis_username();
    this.routeData = this.route.snapshot;
    this.userid = this.routeData.queryParams.userid;
    this.phone = this.routeData.queryParams.phone;
    this.name = this.routeData.queryParams.distric;

    if(this.userid){
      this.username = this.userid
    }
    this.getServerData()
  } 

  getServerData() {
    this.history = []
    this.userService.leavehistoryDetail(this.username).subscribe((response) => {
     this.history = response.result
    }) 
  }

  navigateBack() { 
    if(this.userid){
      this.router.navigate(['/tabs/leave-approval']); 
    } else {
    this.router.navigate(['/tabs/leave-dashboard']); 
  }
  }

}